@startuml

class OilWell {
  + code : string
}

abstract class WellCategory {}

class OnshoreWell {
  + surfaceExtension : float
}

class OffshoreWell {
  + installationYear : int
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class Extraction {
  + quantity : float
}

OilWell "1" -- "*" Extraction
Extraction "*" -- "1" Company
OilWell "1" -- "1" WellCategory
OnshoreWell --|> OilWell
OffshoreWell --|> OilWell
WellCategory "1" -- "*" OnshoreWell
WellCategory "1" -- "*" OffshoreWell
OffshoreWell "0..1" o-- "0..1" GeographicalArea

@enduml

